const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db;try{db=JSON.parse(localStorage.getItem('ethnohod-v2'))}catch{}db=db||{users:[],classes:[{code:'ETNO5',name:'Демонстрационный класс',region:'Башкортостан'}],current:null};
const save=()=>localStorage.setItem('ethnohod-v2',JSON.stringify(db)),user=()=>db.users.find(u=>u.id===db.current);
const lessons=[
{title:'Регион и люди',icon:'🧭',text:'Республика Башкортостан расположена на Южном Урале и в Предуралье. Её столица — Уфа. Здесь живут башкиры, русские, татары и представители других народов. Башкирский и русский — государственные языки республики. Культура региона складывается из разных семейных, языковых и местных традиций: один образ не описывает всех жителей.',question:'Какой город является столицей Башкортостана?',options:['Казань','Уфа','Пермь'],correct:1,why:'Уфа — столица Республики Башкортостан. Казань — столица Татарстана.'},
{title:'Звучание курая',icon:'🎵',text:'Курай — традиционный башкирский духовой инструмент, разновидность продольной флейты. Его название связано с растением, стебель которого используют для изготовления инструмента. Сегодня инструменты делают и из других материалов. Звук возникает благодаря потоку воздуха: исполнитель меняет высоту звука, закрывая отверстия пальцами.',question:'К какой группе инструментов относится курай?',options:['Ударные','Струнные','Духовые'],correct:2,why:'В курае звучит воздушный столб, поэтому это духовой инструмент.'},
{title:'Истории и эпос',icon:'📖',text:'«Урал-батыр» — башкирский народный эпос. В нём герой сталкивается с выбором между личным благополучием и благом других. Эпос передавали устно сказители — сэсэны. Фольклор помогает узнать, какие вопросы волновали людей: жизнь и смерть, ответственность, отношения человека и природы. Сюжет эпоса — художественная традиция, а не историческая хроника.',question:'Кто сохранял и исполнял устные сказания?',options:['Сэсэны','Картографы','Кузнецы'],correct:0,why:'Сэсэны — народные поэты и сказители, хранители устной традиции.'},
{title:'Гостеприимство и кухня',icon:'🍯',text:'Башкортостан известен традициями пчеловодства, в том числе бортничества — содержания пчёл в дуплах деревьев и специально подготовленных бортях. Мёд связан с природой региона и трудом пчеловодов. Блюда и способы их приготовления различаются в семьях и населённых пунктах; многие блюда встречаются у нескольких соседних народов.',question:'Что называют бортничеством?',options:['Изготовление посуды','Особую традицию пчеловодства','Выращивание пшеницы'],correct:1,why:'Бортничество связано с содержанием пчёл в древесных полостях — бортях.'},
{title:'Сабантуй',icon:'🌿',text:'Сабантуй — традиционный праздник, связанный с земледельческим трудом. Он распространён у башкир и татар. На празднике проводят состязания, звучат музыка и песни, встречаются семьи и соседи. Даты и программа зависят от места проведения. Общая традиция может иметь разные местные формы.',question:'С чем исторически связан Сабантуй?',options:['С земледельческим трудом','С мореплаванием','С началом полярной ночи'],correct:0,why:'Название и традиции праздника связаны с плугом и земледельческим трудом.'}
];
const sources='<a href="https://bigenc.ru/" target="_blank" rel="noopener">Большая российская энциклопедия</a> · <a href="https://www.culture.ru/" target="_blank" rel="noopener">Культура.РФ</a> · <a href="https://bashenc.online/" target="_blank" rel="noopener">Башкирская энциклопедия</a>';
const link=(route,text,secondary=false)=>`<a class="btn ${secondary?'secondary':''}" href="#${route}">${text}</a>`;
function layout(title,body){const route=location.hash.slice(1).split('/')[0]||'home';document.body.dataset.route=route;$('#app').innerHTML=`${['home','map'].includes(route)?'':`<div class="page-heading"><h1>${esc(title)}</h1></div>`}${body}<footer class="site-footer"><a class="brand" href="#home">этноход</a><span>Открывать мир. Понимать друг друга.</span><div><a href="#about">О проекте ↗</a><a href="#sources">Источники ↗</a></div><small>© 2026 · Учебный прототип</small></footer>`;$('.header-enter').innerHTML=`<span class="header-enter-label">${user()?'Мой герой':'Создать героя'}</span><svg class="header-enter-arrow" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 19 19 5M9 5h10v10"/></svg>`;$('.header-enter').href=user()?'#profile':'#login';$('#nav').innerHTML=[['map','Карта'],['book','Книга'],['wardrobe','Рюкзак'],['teacher','Учителю']].map(([r,t])=>`<a class="${route===r?'active':''}"${route===r?' aria-current="page"':''} href="#${r}">${t}</a>`).join('');requestAnimationFrame(()=>{document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el))})}
function requireUser(){if(user())return true;location.hash='login';return false}
function render(){if(typeof firstScreenCleanup==='function')firstScreenCleanup();if(typeof visitFlushTime==='function')visitFlushTime();if(typeof visitPhraseAudio!=='undefined'&&visitPhraseAudio)visitPhraseAudio.pause();const [route='home',arg]=(location.hash.slice(1)||'home').split('/'),u=user();
if(['map','region','story','lesson','quiz','result','profile','tutorial','book','wardrobe'].includes(route)){if(!u){location.hash='home';return}if(!u.character){location.hash='character';return}}
if(route==='map'&&u&&!u.tutorialDone){location.hash='tutorial';return}
if(route==='home'){layout('Живой атлас культур',firstScreenHome(u));wireFirstScreen()}
else if(route==='login')visitLoginPage(arg==='return');
else if(route==='tutorial'){layout('Путешествия начинаются с любопытства',visitTutorialPage(u));wireVisitTutorial(u)}
else if(route==='book'){layout('Твоя книга регионов',visitBookPage(u,arg));wireVisitBook(u)}
else if(route==='wardrobe'){layout('Гардероб и рюкзак',visitWardrobePage(u));wireVisitWardrobe(u)}
else if(route==='character'){if(arg==='edit'&&u){pendingJoin=null;sessionStorage.removeItem('ethnohod-pending-join');creatorState=null}renderCharacterStudio();}
else if(route==='map'){layout('Карта открытий',discoveryAtlasPage(u));wireDiscoveryAtlas(u)}
else if(route==='story'){layout('Праздник с Данияром',storyPage(u));wireStoryGame(u)}
else if(route==='region'){if(!requireUser())return;layout('Башкортостан',visitBookPage(u,'bashkortostan'));wireVisitBook(u)}
else if(route==='lesson'){if(!requireUser())return;let i=Number(arg),l=lessons[i];if(!l){location.hash='region';return}layout(l.title,gameLessonPage(l,i,u));document.querySelectorAll('[data-a]').forEach(b=>b.onclick=()=>{let ok=+b.dataset.a===l.correct;$('#feedback').textContent=(ok?'Верно! ':'Попробуй ещё. ')+l.why;if(ok){if(!u.completed.includes(i))u.completed.push(i);save();document.querySelectorAll('[data-a]').forEach(x=>x.disabled=true);$('#next').innerHTML=link(i<4?'lesson/'+(i+1):'region',i<4?'Следующая остановка':'Вернуться к маршруту')}})}
else if(route==='quiz'){if(!requireUser())return;if(u.completed.length<5){location.hash='region';return}let qi=0,answers=[];layout('Итоговое испытание','<div class="card" id="quiz"></div>');function draw(){let l=lessons[qi];$('#quiz').innerHTML=`<h2>${l.question}</h2><p class="quiz-count">Вопрос ${qi+1} из 5</p>${l.options.map((o,j)=>`<button class="answer" data-q="${j}">${o}</button>`).join('')}`;document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>{answers.push(+b.dataset.q);if(++qi<5)draw();else{u.attempts.push({date:new Date().toISOString(),answers,score:answers.filter((a,i)=>a===lessons[i].correct).length});save();location.hash='result'}})}draw()}
else if(route==='result'){if(!requireUser())return;let a=u.attempts.at(-1);if(!a){location.hash='region';return}layout('Твои открытия',gameResultPage(a,u))}
else if(route==='profile'){if(!requireUser())return;layout('Мой профиль',gameProfilePage(u));document.querySelector('[data-equip-burek]')?.addEventListener('click',()=>{u.equippedHat=u.equippedHat==='burek'?null:'burek';save();render()})}
else if(route==='teacher'){layout('Кабинет учителя',visitTeacherPage());wireVisitTeacher()}
else if(route==='class'){layout('Результаты класса',visitClassPage(arg));wireVisitClass(arg)}
else if(route==='guide'){layout('Твой спутник',visitGuidePage());wireVisitGuide()}
else if(route==='sources')layout('Материалы и источники',`<p>Маршрут знакомит с отдельными примерами культуры Башкортостана. Он не охватывает всё многообразие республики и не заменяет учебник.</p><div class="card"><h2>Где читать дальше</h2><p>${sources}</p><p>В энциклопедиях ищи статьи «Башкортостан», «Курай», «Урал-батыр», «Сабантуй» и «Бортничество».</p></div><p class="map-credit">Географические контуры: <a href="https://github.com/freOn1131/RuGeo" target="_blank" rel="noopener">RuGeo</a>. Проекция Альберса; контуры упрощены для интерактивного атласа.</p><h2>Содержание маршрута</h2>${lessons.map(l=>`<article class="card"><h3>${l.icon} ${l.title}</h3><p>${l.text}</p></article>`).join('')}<p class="notice">Перед использованием в школьной программе нужны редакционная проверка, точные ссылки на статьи и согласование с педагогом.</p>`);
else if(route==='about')layout('О проекте',`<p>Этноход — учебное путешествие по культурам народов России. Его задача — поддержать интерес к культурному многообразию через короткие истории, задания и обсуждение с учителем.</p><div class="card"><h2>Что работает сейчас</h2><p>Вход по коду, профили учеников, пять учебных тем, проверка ответов, итоговое испытание, награда, создание классов, таблица результатов и экспорт.</p><h2>Как хранятся данные</h2><p>Данные находятся в localStorage этого браузера. Очистка данных сайта удалит их. Это прототип без серверной авторизации и синхронизации устройств. Не вводи реальные персональные данные.</p><h2>Дальнейшее развитие</h2><p>Сервер и база данных, защищённый кабинет учителя, редакционная проверка содержания, новые регионы и проводник с ответами по проверенным источникам.</p></div>`);
else{layout('Страница не найдена',link('home','На главную'))}
document.title=(route==='home'?'Этноход — живой атлас культур':($('#app h1')?.textContent||'Этноход')+' · Этноход');if(document.activeElement?.tagName!=='INPUT')$('#app').focus({preventScroll:true});window.scrollTo({top:0,left:0,behavior:"instant"})}window.addEventListener('hashchange',render);render();
